using System.Diagnostics;using System.Text.Json;using Dip.Application.Features.Intelligence;using Dip.Application.Features.QualityAutomation;
namespace Dip.Infrastructure.Intelligence;
public sealed class MinimumHardwareRunner:IMinimumHardwareRunner
{
    readonly IQaWorkspaceResolver _workspace;public MinimumHardwareRunner(IQaWorkspaceResolver workspace){_workspace=workspace;}
    public async Task<MinimumHardwareResult> FindAsync(MinimumHardwareRequest r,string artifactRoot,CancellationToken ct){var ws=_workspace.Resolve(r.WorkspaceRelativePath);if(Path.IsPathRooted(r.RuntimeExecutable))throw new InvalidOperationException("Runtime executable must be workspace-relative.");var exe=Path.GetFullPath(Path.Combine(ws,r.RuntimeExecutable));var prefix=ws.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!exe.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Executable escapes workspace.");async Task<bool> Probe(decimal cpu,decimal gpu,decimal mem,decimal storage){var psi=new ProcessStartInfo(exe){WorkingDirectory=ws,UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var a in r.RuntimeArguments)psi.ArgumentList.Add(a);psi.Environment["DIP_CPU_BUDGET_PERCENT"]=cpu.ToString(System.Globalization.CultureInfo.InvariantCulture);psi.Environment["DIP_GPU_BUDGET_PERCENT"]=gpu.ToString(System.Globalization.CultureInfo.InvariantCulture);psi.Environment["DIP_MEMORY_BUDGET_MB"]=Math.Max(128,(long)(r.MaximumMemoryMb*mem/100m)).ToString();psi.Environment["DIP_STORAGE_BUDGET_PERCENT"]=storage.ToString(System.Globalization.CultureInfo.InvariantCulture);using var p=Process.Start(psi)??throw new InvalidOperationException("Could not start target.");using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromMinutes(5));try{await p.WaitForExitAsync(timeout.Token);}catch(OperationCanceledException)when(!ct.IsCancellationRequested){try{p.Kill(true);}catch{}return false;}return p.ExitCode==0;}async Task<decimal> Search(Func<decimal,Task<bool>> f){decimal lo=10,hi=100;for(int i=0;i<Math.Clamp(r.MaxIterations,3,12);i++){var mid=(lo+hi)/2;if(await f(mid))hi=mid;else lo=mid;}return decimal.Round(hi,2);}var cpu=await Search(x=>Probe(x,100,100,100));var gpu=await Search(x=>Probe(100,x,100,100));var mem=await Search(x=>Probe(100,100,x,100));var storage=await Search(x=>Probe(100,100,100,x));decimal Safe(decimal x)=>Math.Min(100,decimal.Round(x*1.2m+5,2));var payload=JsonSerializer.Serialize(new{method="bounded-binary-search",simulated=true,realDevice=false,cpu,gpu,mem,storage,targetFps=r.TargetFps,iterations=r.MaxIterations});await File.WriteAllTextAsync(Path.Combine(artifactRoot,"minimum-hardware.json"),payload,ct);return new(cpu,gpu,mem,storage,Safe(cpu),Safe(gpu),Safe(mem),Safe(storage),75,payload);}
}
